  html+=sec('Run sheet')+'<div class="grid g21">'+panel(bookMode==='up'?'Today & upcoming':'Latest jobs',runHtml,fJ?'form/'+fJ.formId+'/responses':'')+panel('Jobs by team this week',twHtml,fT?'form/'+fT.formId+'/responses':'')+'</div>';
  var iOpen=issues.slice().filter(function(x){return (x.answers||{}).status!=='resolved';});
  var sevOrd={high:0,medium:1,low:2};
  iOpen.sort(function(x,y){var xs=sevOrd[(x.answers||{}).severity];var ys=sevOrd[(y.answers||{}).severity];return (xs==null?3:xs)-(ys==null?3:ys);});
  var itMap=optionMap(fI,'issue_type'),sevMap=optionMap(fI,'severity');
  var issHtml='';
  for(var p3=0;p3<Math.min(5,iOpen.length);p3++){var ic=iOpen[p3].answers||{};var sc=ic.severity==='high'?'bad':ic.severity==='medium'?'warn':'neutral';
    issHtml+=rowItem(h(labelFor(itMap,ic.issue_type)),h(refName(cn,ic.client)||'Client')+' \u00b7 '+h(fmtDate(iOpen[p3].submittedAt)),pill(labelFor(sevMap,ic.severity),sc));}
  if(!issHtml)issHtml=emptyBlock(I.check,issues.length?'Every client issue is resolved. Nice work.':'Client issues you log appear here, most urgent first.',fI?fI.formId:'','+ Log issue');
  var lowList=supplies.slice().filter(function(x){var st=(x.answers||{}).status;return st==='low'||st==='out';});
  lowList.sort(function(x,y){var o={out:0,low:1};return (o[(x.answers||{}).status]==null?9:o[(x.answers||{}).status])-(o[(y.answers||{}).status]==null?9:o[(y.answers||{}).status]);});
  var spMap=optionMap(fS,'status'),scatMap=optionMap(fS,'category');
  var lowHtml='';
  for(var p4=0;p4<Math.min(5,lowList.length);p4++){var lc=lowList[p4].answers||{};
    lowHtml+=rowItem(h(lc.supply_item||'Item'),h(labelFor(scatMap,lc.category)),pill(labelFor(spMap,lc.status),lc.status==='out'?'bad':'warn'));}
  if(!lowHtml)lowHtml=emptyBlock(I.box,supplies.length?'Every supply is stocked above its reorder point.':'Track your supplies to get low-stock alerts here.',fS?fS.formId:'','+ Restock');
  html+=sec('Issues & supplies')+'<div class="grid g11">'+panel('Open issues',issHtml,fI?'form/'+fI.formId+'/responses':'')+panel('Low on stock',lowHtml,fS?'form/'+fS.formId+'/responses':'')+'</div>';
  html+=sec('Quick actions')+acts([{nav:fJ?fJ.formId:'',label:'New job',icon:I.cal},{nav:fQ?fQ.formId:'',label:'Quality check',icon:I.check},{nav:fI?fI.formId:'',label:'Log issue',icon:I.alert},{nav:fS?fS.formId:'',label:'Restock',icon:I.box},{nav:fC?fC.formId:'',label:'New client',icon:I.user}]);
  html+='</div>';root.innerHTML=html;wire(root);
}
main();
